actions.script:
outerColumnsList = []
outerRecordsList = []

const limitInt = parseInt(limit || "500", 10)

// make sure SQL comes in secure parameter (body, etc no URL)
sql = ec.web.secureRequestParameters.sql
if (sql && groupName) {
    messageList = []
    // JDBC runs a script of several statements and returns each result; here each statement runs by itself
    try {
        const result = ec.entity.runSqlStatement(String(groupName), String(sql), limitInt)
        if (result.rowsAffected != null) {
            messageList.push(ec.resource.expand('Query altered ${rowsAffected} rows.', '', {rowsAffected: result.rowsAffected}))
        } else {
            outerColumnsList.push(result.columns)
            outerRecordsList.push(result.records)
            if (result.limitReached) {
                messageList.push(ec.resource.expand('Only showing first ${limit} rows.', '', {limit: limitInt}))
            } else {
                messageList.push(ec.resource.expand('Showing all ${count} results.', '', {count: result.records.length}))
            }
        }
    } catch (e) {
        messageList.push(String(e))
        ec.logger.log(200, "Error running SQL query in SqlRunner", e)
    }
}

render-mode.text:
${JSON.stringify((outerColumnsList || []).flatMap((columns, columnsIndex) => {
            const records = outerRecordsList[columnsIndex] || []
            return [{t: 'text', id: 'SqlResultTitle' + columnsIndex, style: 'h5', text: 'Result Set ' + (columnsIndex + 1)},
                {t: 'formList', id: 'SqlResult' + columnsIndex, name: 'SqlResult' + columnsIndex,
                    columns: columns.map((column) => ({title: String(column)})),
                    rows: records.map((record, recordIndex) => ({id: String(recordIndex),
                        cells: record.map((curField) => curField == null ? '' : String(ec.l10n.format(curField, '')))})),
                    paging: {index: 0, size: records.length, count: records.length}}]
        }))}
